def concert(text):
    a = list(map(int, text.split()))[1:]
    stack = []
    answer = 0
    for h in a:
        same = 1
        while stack and stack[-1][0] < h:
            answer += stack.pop()[1]
        if stack:
            if stack[-1][0] == h:
                same += stack[-1][1]
                answer += stack.pop()[1]
                if stack:
                    answer += 1
            else:
                answer += 1
        stack.append((h, same))
    return str(answer)
