def settle(board):
    columns = [list(row) for row in board]
    while True:
        removed = set()
        for (x, col) in enumerate(columns):
            for (y, color) in enumerate(col):
                if y + 2 < len(col) and col[y + 1] == color == col[y + 2]:
                    end = y + 3
                    while end < len(col) and col[end] == color:
                        end += 1
                    removed.update(((x, j) for j in range(y, end)))
                if x + 2 < 5 and y < len(columns[x + 1]) and (y < len(columns[x + 2])) and (columns[x + 1][y] == color == columns[x + 2][y]):
                    end = x + 3
                    while end < 5 and y < len(columns[end]) and (columns[end][y] == color):
                        end += 1
                    removed.update(((i, y) for i in range(x, end)))
        if not removed:
            return tuple((tuple(row) for row in columns))
        columns = [[v for (y, v) in enumerate(col) if (x, y) not in removed] for (x, col) in enumerate(columns)]

def mayan(text):
    lines = text.splitlines()
    steps = int(lines[0])
    initial = tuple((tuple(map(int, line.split()))[:-1] for line in lines[1:]))

    @lru_cache(None)
    def visit(board, left):
        if not left:
            return () if not any(board) else None
        counts = Counter((v for row in board for v in row))
        if any((v < 3 for v in counts.values())):
            return None
        for (x, col) in enumerate(board):
            for y in range(len(col)):
                for direction in (1, -1):
                    z = x + direction
                    if not 0 <= z < 5:
                        continue
                    moved = [list(row) for row in board]
                    if y < len(moved[z]):
                        (moved[x][y], moved[z][y]) = (moved[z][y], moved[x][y])
                    else:
                        moved[z].append(moved[x].pop(y))
                    nxt = settle(moved)
                    tail = visit(nxt, left - 1)
                    if tail is not None:
                        return ((x, y, direction),) + tail
        return None
    result = visit(initial, steps)
    return '-1' if result is None else '\n'.join((' '.join(map(str, row)) for row in result))
