def orderly(text):
    (k, line) = text.split('\n', 1)
    s = line.rstrip('\r\n')
    if int(k) > 1:
        return ''.join(sorted(s))
    doubled = s + s
    (i, j, offset) = (0, 1, 0)
    n = len(s)
    while i < n and j < n and (offset < n):
        (a, b) = (doubled[i + offset], doubled[j + offset])
        if a == b:
            offset += 1
            continue
        if a > b:
            i = i + offset + 1
            if i == j:
                i += 1
        else:
            j = j + offset + 1
            if i == j:
                j += 1
        offset = 0
    start = min(i, j)
    return doubled[start:start + n]
