def stones(text):
    v = list(map(int, text.split()))
    n = v[0]
    parents = list(range(n))
    rows = {}
    cols = {}

    def root(i):
        while parents[i] != i:
            parents[i] = parents[parents[i]]
            i = parents[i]
        return i
    for (i, (x, y)) in enumerate(zip(v[1::2], v[2::2])):
        for (seen, key) in ((rows, x), (cols, y)):
            if key in seen:
                parents[root(i)] = root(seen[key])
            else:
                seen[key] = i
    return str(n - len({root(i) for i in range(n)}))
