def one_zero(text):
    (a, b) = map(int, text.split())
    answer = 0
    for width in range(2, b.bit_length() + 1):
        for zero in range(width - 1):
            value = (1 << width) - 1 - (1 << zero)
            if a <= value <= b:
                answer += 1
    return str(answer)
