def digit_count(text):
    (left, right, digit) = map(int, text.split())

    def prefix(n):
        total = 0
        factor = 1
        while factor <= n:
            high = n // (10 * factor)
            cur = n // factor % 10
            low = n % factor
            if digit:
                total += high * factor
                if cur > digit:
                    total += factor
                elif cur == digit:
                    total += low + 1
            elif high:
                total += (high - 1) * factor
                if cur > 0:
                    total += factor
                else:
                    total += low + 1
            factor *= 10
        return total
    return str(prefix(right) - prefix(left - 1))
