def dominoes(text):
    v = list(map(int, text.split()))
    out = []
    for (n, m) in zip(v[::2], v[1::2]):
        if not n and (not m):
            break
        if n > m:
            (n, m) = (m, n)

        @lru_cache(None)
        def transitions(mask):
            answer = []

            def fill(i, outmask):
                if i == n:
                    answer.append(outmask)
                    return
                if mask >> i & 1:
                    fill(i + 1, outmask)
                    return
                fill(i + 1, outmask | 1 << i)
                if i + 1 < n and (not mask >> i + 1 & 1):
                    fill(i + 2, outmask)
            fill(0, 0)
            return answer
        dp = {0: 1}
        for _ in range(m):
            nxt = defaultdict(int)
            for (mask, count) in dp.items():
                for outmask in transitions(mask):
                    nxt[outmask] += count
            dp = nxt
        out.append(str(dp.get(0, 0)))
    return '\n'.join(out)
