def gene(text):
    words = text.split()
    (start, end) = words[:2]
    bank = set(words[2:])
    q = deque([(start, 0)])
    seen = {start}
    while q:
        (u, d) = q.popleft()
        if u == end:
            return str(d)
        for i in range(8):
            for c in 'ACGT':
                v = u[:i] + c + u[i + 1:]
                if v in bank and v not in seen:
                    seen.add(v)
                    q.append((v, d + 1))
    return '-1'
