def three_sum(text):
    v = list(map(int, text.split()))
    a = sorted(v[1:])
    answer = 0
    for i in range(len(a) - 2):
        if i and a[i] == a[i - 1]:
            continue
        (left, right) = (i + 1, len(a) - 1)
        while left < right:
            value = a[i] + a[left] + a[right]
            if value == 0:
                answer += 1
                (x, y) = (a[left], a[right])
                while left < right and a[left] == x:
                    left += 1
                while left < right and a[right] == y:
                    right -= 1
            elif value < 0:
                left += 1
            else:
                right -= 1
    return str(answer)
