def medians(text):
    rows = text.splitlines()
    at = 1
    out = []
    for _ in range(int(rows[0])):
        count = int(rows[at])
        at += 1
        low = []
        high = []
        for line in rows[at:at + count]:
            words = line.split()
            op = words[0]
            if op == 'I':
                value = int(words[1])
                if not low or value <= -low[0]:
                    heapq.heappush(low, -value)
                else:
                    heapq.heappush(high, value)
            elif op == 'D':
                heapq.heappop(low)
            else:
                out.append(str(-low[0]))
            while len(low) > len(high) + 1:
                heapq.heappush(high, -heapq.heappop(low))
            while len(high) > len(low):
                heapq.heappush(low, -heapq.heappop(high))
        at += count
    return '\n'.join(out)
