def jobs(text):
    v = list(map(int, text.split()))
    (n, k) = v[:2]
    a = sorted(v[2:], reverse=True)
    low = max(max(a), (sum(a) + k - 1) // k)
    high = sum(a)

    def feasible(limit):
        loads = [0] * k

        def visit(i):
            if i == n:
                return True
            seen = set()
            for j in range(k):
                if loads[j] in seen or loads[j] + a[i] > limit:
                    continue
                seen.add(loads[j])
                loads[j] += a[i]
                if visit(i + 1):
                    return True
                loads[j] -= a[i]
                if loads[j] == 0:
                    break
            return False
        return visit(0)
    while low < high:
        mid = (low + high) // 2
        if feasible(mid):
            high = mid
        else:
            low = mid + 1
    return str(low)
import sys
