def merchants(text):
    lines = text.splitlines()
    (n, m) = map(int, lines[0].split())
    values = list(map(int, lines[1].split()))
    adj = [[] for i in range(n)]
    for line in lines[2:m + 2]:
        (a, b) = map(int, line.split())
        adj[a - 1].append(b - 1)
        adj[b - 1].append(a - 1)
    colors = [-1] * n
    colors[0] = 0
    q = deque([0])
    bipartite = True
    while q:
        u = q.popleft()
        for v in adj[u]:
            if colors[v] < 0:
                colors[v] = colors[u] ^ 1
                q.append(v)
            elif colors[v] == colors[u]:
                bipartite = False
    inf = 10 ** 100

    def priority(identifier):
        z = identifier + 11400714819323198485 & (1 << 64) - 1
        z = (z ^ z >> 30) * 13787848793156543929 & (1 << 64) - 1
        z = (z ^ z >> 27) * 10723151780598845931 & (1 << 64) - 1
        return z ^ z >> 31

    def node(value, i):
        return [(value, i), priority(i), None, None, colors[i], value, colors[i], value, colors[i], inf]

    def refresh(t):
        if t is None:
            return t
        value = t[0][0]
        color = t[4]
        t[5:10] = [value, color, value, color, inf]
        (left, right) = (t[2], t[3])
        if left:
            t[5:7] = left[5:7]
            t[9] = min(t[9], left[9])
            if left[8] != color:
                t[9] = min(t[9], value - left[7])
        if right:
            t[7:9] = right[7:9]
            t[9] = min(t[9], right[9])
            if right[6] != color:
                t[9] = min(t[9], right[5] - value)
        return t

    def merge(a, b):
        if a is None:
            return b
        if b is None:
            return a
        if a[1] < b[1]:
            a[3] = merge(a[3], b)
            return refresh(a)
        b[2] = merge(a, b[2])
        return refresh(b)

    def split(t, key):
        if t is None:
            return (None, None)
        if t[0] < key:
            (a, b) = split(t[3], key)
            t[3] = a
            return (refresh(t), b)
        (a, b) = split(t[2], key)
        t[2] = b
        return (a, refresh(t))

    def insert(t, x):
        if t is None:
            return x
        if x[1] < t[1]:
            (x[2], x[3]) = split(t, x[0])
            return refresh(x)
        child = 2 if x[0] < t[0] else 3
        t[child] = insert(t[child], x)
        return refresh(t)

    def erase(t, key):
        if t[0] == key:
            return merge(t[2], t[3])
        child = 2 if key < t[0] else 3
        t[child] = erase(t[child], key)
        return refresh(t)
    root = None
    if bipartite:
        for (i, value) in enumerate(values):
            root = insert(root, node(value, i))
    out = []
    for line in lines[m + 3:]:
        (op, a, b) = map(int, line.split())
        a -= 1
        if op == 0:
            if bipartite:
                root = erase(root, (values[a], a))
                root = insert(root, node(b, a))
            values[a] = b
        elif not bipartite or colors[a] == colors[b - 1]:
            out.append('0')
        else:
            out.append(str(root[9]))
    return '\n'.join(out)
