def integer_break(text):
    n = int(text)
    if n <= 3:
        return str(n - 1)
    (threes, rest) = divmod(n, 3)
    if rest == 1:
        threes -= 1
        rest = 4
    return str(3 ** threes * (rest if rest else 1))
