def concatenated(text):
 words=text.split();dictionary=set(words);out=[]
 for word in words:
  reachable=[False]*(len(word)+1);reachable[0]=True
  for end in range(1,len(word)+1):reachable[end]=any(reachable[start] and word[start:end] in dictionary and not(start==0 and end==len(word)) for start in range(end))
  if reachable[-1]:out.append(word)
 return ' '.join(out) if out else 'None'
