def ice(text):
 n,t,k,d=map(int,text.split());single=((n+k-1)//k)*t;before=single-1;made=(before//t+max(0,before-d)//t)*k;return 'YES' if made>=n else 'NO'
def fitness(text):
 v=list(map(int,text.split()));n=v[0];a=sorted(s-h for h,s in zip(v[1:1+n],v[n+1:]));left,right=0,n-1;total=0
