def coins(text):
 v=list(map(int,text.split()));n,m=v[:2];denominations=v[2:];dp=[0]+[m+1]*m
 for amount in range(1,m+1):dp[amount]=min([dp[amount]]+[dp[amount-c]+1 for c in denominations if c<=amount])
